import {CORES,BLADES,DISCS,TIPS,ACTIONS,ACTION_LABELS,makeBuild,createBattle,resolveTurn,COMPONENT_COUNT} from './engine.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const labels={home:'COMMAND DECK',arena:'BATTLE ARENA',workshop:'BEYBLADE WORKSHOP',collection:'COMPONENT COLLECTION',rankings:'RANKINGS',history:'MATCH HISTORY'};
const defaultParts={core:'C01',blade:'B01',disc:'D01',tip:'T01'};
const stored=(()=>{try{return JSON.parse(localStorage.getItem('arena-save')||'{}')}catch{return {}}})();
const app={view:'home',parts:{...defaultParts,...stored.parts},buildName:stored.buildName||'AETHERION',profile:stored.profile||'KAIRO',savedBuilds:stored.savedBuilds||[],history:stored.history||[],tab:'core',battle:null,phase:'idle',p1Action:null,p2Action:null,toastTimer:null,sound:false};
function save(){localStorage.setItem('arena-save',JSON.stringify({parts:app.parts,buildName:app.buildName,profile:app.profile,savedBuilds:app.savedBuilds,history:app.history}))}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function currentBuild(){return makeBuild({...app.parts,name:app.buildName.trim()||'UNTITLED'})}
function opponentBuild(){return makeBuild({core:'C11',blade:'B03',disc:'D04',tip:'T06',name:'VOLT REAPER'})}
function showToast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(app.toastTimer);app.toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function statsMarkup(stats,compact=false){return Object.entries(stats).map(([key,value])=>`<div class="stat-row"><span>${key.toUpperCase()}</span><div class="stat-track"><div class="stat-fill" style="width:${value}%"></div></div><b class="stat-value">${value}</b></div>`).join('')}
function artMarkup(extra=''){return `<div class="blade-art ${extra}"><i class="blade-shine"></i></div>`}
function collectionSummary(){return `<span>${app.savedBuilds.length} saved builds</span><span>${COMPONENT_COUNT.toLocaleString()} possible builds</span>`}
function go(view){if(!labels[view])return;app.view=view;app.tab='core';render();window.scrollTo(0,0);$('#pageLabel').textContent=labels[view]}
function navActive(){ $$('.nav-item').forEach(button=>button.classList.toggle('active',button.dataset.view===app.view));$('#pageLabel').textContent=labels[app.view]||'COMMAND DECK'}
function render(){const root=$('#viewRoot');root.innerHTML=({home:homeView,workshop:workshopView,collection:collectionView,arena:arenaView,rankings:rankingsView,history:historyView}[app.view]||homeView)();navActive();bindView();$('#profileName').textContent=app.profile.toUpperCase();$('#topAvatar').textContent=app.profile.slice(0,1).toUpperCase()}
function bindView(){ $$('[data-view]').forEach(x=>x.onclick=()=>go(x.dataset.view));$$('[data-start]').forEach(x=>x.onclick=()=>startBattle());$$('[data-tab]').forEach(x=>x.onclick=()=>{app.tab=x.dataset.tab;render()});$$('[data-part]').forEach(x=>x.onclick=()=>{app.parts[app.tab]=x.dataset.part;render();save()});$$('[data-action]').forEach(x=>x.onclick=()=>chooseAction(x.dataset.action));$$('[data-restart]').forEach(x=>x.onclick=()=>startBattle());$$('[data-rematch]').forEach(x=>x.onclick=()=>startBattle());$$('[data-privacy]').forEach(x=>x.onclick=()=>passDevice());$$('[data-save-build]').forEach(x=>x.onclick=saveBuild);$$('[data-new-build]').forEach(x=>x.onclick=()=>{app.parts={...defaultParts};app.buildName='AETHERION';app.view='workshop';render()});$$('[data-use-build]').forEach(x=>x.onclick=()=>loadBuild(Number(x.dataset.useBuild)));$$('[data-delete-build]').forEach(x=>x.onclick=()=>deleteBuild(Number(x.dataset.deleteBuild)));
 const name=$('#buildNameInput');if(name)name.oninput=()=>{app.buildName=name.value.toUpperCase();$('.preview-bey-name h3').textContent=app.buildName||'UNTITLED';$('.preview-components').textContent=componentLine(currentBuild());$('.type-tag').textContent=currentBuild().classification;$('.preview-stats').innerHTML=statsMarkup(currentBuild().stats);save()};
 const profile=$('#profileButton');if(profile)profile.onclick=()=>{const name=prompt('Blader callsign (local profile):',app.profile);if(name?.trim()){app.profile=name.trim().slice(0,16);save();render()}};
}
function homeView(){const build=currentBuild(),last=app.history.slice(-3).reverse();return `<div class="eyebrow">SEASON 01 / OPEN CIRCUIT</div><h1 class="page-title">Your command deck.</h1><p class="page-subtitle">Every part is a decision. Tune your build, read the arena, and take the ring.</p>
<div class="hero-grid"><section class="hero-card"><div class="eyebrow">LOCAL VERSUS · TWO BLADERS · ONE DEVICE</div><h2 class="hero-title">BUILD YOUR<br><span>LEGEND.</span></h2><p class="hero-copy">Read the matchup. Pick your move. Make every collision count. Your next rival is waiting in the arena.</p><div class="hero-cta"><button class="primary-button" data-start>ENTER THE ARENA <span>↗</span></button><button class="secondary-button" data-view="workshop">TUNE YOUR BUILD</button></div><div class="hero-art">${artMarkup()}<span class="blade-shine"></span></div></section>
<div class="side-stack"><section class="mini-card"><span class="eyebrow">THE WORKSHOP</span><span class="mini-stat">${COMPONENT_COUNT.toLocaleString()}</span><h3>One of a kind.</h3><p>15 cosmetic cores. 24 performance components. One signature build.</p><button class="text-link mini-cta" data-view="workshop">OPEN WORKSHOP ↗</button></section><section class="mini-card"><span class="eyebrow">FAIR PLAY</span><h3>Skill over spend.</h3><p>No rarity. No boosts. Component trade-offs are visible, and the same parts are open to every blader.</p><span class="mini-cta" style="color:#7f8e9d">BUILT FOR COMPETITION</span></section></div></div>
<div class="section-heading"><div><h2>Your active Bey</h2><p>Current workshop build · edits save automatically</p></div><button class="text-link" data-view="workshop">EDIT BUILD ↗</button></div>
<div class="dashboard-grid"><section class="panel build-showcase"><div class="build-visual">${artMarkup()}</div><div class="build-copy"><div class="build-name-row"><h3>${esc(build.name)}</h3><span class="type-tag">${build.classification.toUpperCase()}</span></div><div class="component-line">${build.core} / ${build.blade} / ${build.disc} / ${build.tip}</div><div class="stat-list">${statsMarkup(build.stats)}</div></div></section><section class="panel match-card"><span class="eyebrow">READY WHEN YOU ARE</span><h3>Local versus</h3><p>Pass the device between turns. Actions stay hidden until both bladers commit.</p><div class="match-meta"><span>MODE <b>LOCAL</b></span><span>BEST OF <b>1</b></span><span>TIME <b>~4 MIN</b></span></div><button class="primary-button" data-start>START MATCH ↗</button></section></div>
<div class="section-heading"><div><h2>Recent matches</h2><p>Your local battle record</p></div><button class="text-link" data-view="history">ALL MATCHES ↗</button></div>${last.length?`<section class="panel match-history-list">${last.map(historyRow).join('')}</section>`:`<div class="empty-state"><b>No battles logged.</b>First launch is yours to make.<br><br><button class="secondary-button" data-start>PLAY FIRST MATCH</button></div>`}`}
function componentLine(build){return `${build.core} / ${build.blade} / ${build.disc} / ${build.tip}`}
function historyRow(match){return `<div class="history-row"><span class="history-mark">${match.winner==='you'?'✓':match.winner==='draw'?'=':'×'}</span><div><b>${match.winner==='you'?'VICTORY':match.winner==='draw'?'DRAW':'DEFEAT'} · ${esc(match.reason)}</b><small>${esc(match.build||'YOUR BUILD')} vs ${esc(match.opponent||'VOLT REAPER')}</small></div><span class="result-pill">${match.turns} TURNS</span><time class="history-time">${esc(match.date)}</time></div>`}

