const componentSets={core:CORES,blade:BLADES,disc:DISCS,tip:TIPS};
function componentTitle(kind){return ({core:'Cosmetic core',blade:'Blade · attack / impact',disc:'Disc · mobility / stamina',tip:'Tip · movement / stability'})[kind]}
function componentDescription(kind,item){if(kind==='core')return item.name;if(kind==='blade')return `AP ${item.ap} · LI ${item.li}`;if(kind==='disc')return `MS ${item.ms} · ST ${item.st}`;return `MB ${item.mb} · SM ${item.sm}`}
function componentOption(kind,item){const selected=app.parts[kind]===item.id;return `<button class="component-option ${selected?'selected':''} ${kind==='core'?'core-option':''}" data-part="${item.id}">${kind==='core'?`<i class="core-swatch" style="--swatch:${item.color};background:${item.color}"></i>`:''}<span><b>${item.id}</b><small>${esc(componentDescription(kind,item))}</small></span></button>`}
function workshopView(){const build=currentBuild(),list=componentSets[app.tab];return `<div class="eyebrow">YOUR GARAGE / LIVE BUILD CALCULATOR</div><h1 class="page-title">The workshop.</h1><p class="page-subtitle">Four parts, one identity. See every stat shift as you tune your Beyblade. Cores are cosmetic; blades, discs, and tips carry explicit trade-offs.</p><div class="workshop-layout"><section class="panel builder-panel"><div class="panel-caption">01 / SELECT COMPONENTS</div><div class="component-tabs">${[['core','CORE'],['blade','BLADE'],['disc','DISC'],['tip','TIP']].map(([key,label])=>`<button class="component-tab ${app.tab===key?'selected':''}" data-tab="${key}"><strong>${label}</strong>${key==='core'?'COSMETIC':'8 OPTIONS'}</button>`).join('')}</div><div class="selection-heading"><b>${componentTitle(app.tab)}</b><span>${list.length} AVAILABLE</span></div><div class="option-grid">${list.map(item=>componentOption(app.tab,item)).join('')}</div><div class="builder-actions"><button class="secondary-button" data-new-build>RESET BUILD</button><button class="primary-button" data-save-build>SAVE TO GARAGE</button></div><p class="saved-build">Build choices save automatically on this device. No account or network required.</p></section>
<section class="panel preview-panel"><div class="panel-caption">02 / LIVE BUILD PREVIEW</div><div class="preview-art-wrap">${artMarkup()}</div><div class="preview-bey-name"><h3>${esc(build.name)}</h3><span class="type-tag">${build.classification.toUpperCase()}</span></div><input id="buildNameInput" aria-label="Beyblade name" maxlength="20" value="${esc(build.name)}" placeholder="Name your Bey" /><div class="preview-components">${componentLine(build)}</div><div class="preview-stats">${statsMarkup(build.stats)}</div><div class="classification-note"><b>TYPE READ:</b> ${build.classification==='Balanced'?'No single combat stat dominates this build.':`${build.classification} leads this configuration.`} Core color is visual only; all cores share identical performance.</div></section></div>`}
function collectionView(){return `<div class="eyebrow">YOUR GARAGE / COMPONENT INDEX</div><h1 class="page-title">The collection.</h1><p class="page-subtitle">Every part is available from the start. Performance components remain trade-offs, never rarity tiers.</p><div class="section-heading"><div><h2>15 cosmetic cores</h2><p>Color only · no combat advantage</p></div><span class="panel-caption">${collectionSummary()[0]}</span></div><div class="collection-grid">${CORES.map(core=>`<article class="collection-card"><i class="core-swatch" style="--swatch:${core.color};background:${core.color}"></i><b>${esc(core.name)}</b><small>${core.id} · COSMETIC CORE</small></article>`).join('')}</div><div class="section-heading"><div><h2>Performance components</h2><p>24 options · explicit paired-stat conservation</p></div></div><div class="two-col"><section class="panel"><div class="panel-pad"><h3 class="panel-title">Blades · AP + LI = 80</h3><p class="panel-caption">ATTACK POTENTIAL / IMPACT LOAD</p></div><div class="table-list">${BLADES.map(x=>`<div class="table-row"><span class="rank-number">${x.id}</span><div><b>AP ${x.ap}</b><small>Impact load ${x.li}</small></div><span class="table-score">${x.ap+x.li} TOTAL</span></div>`).join('')}</div></section><section class="panel"><div class="panel-pad"><h3 class="panel-title">Discs · MS + ST = 100</h3><p class="panel-caption">MOBILITY / STAMINA</p></div><div class="table-list">${DISCS.map(x=>`<div class="table-row"><span class="rank-number">${x.id}</span><div><b>MS ${x.ms}</b><small>Stamina ${x.st}</small></div><span class="table-score">${x.ms+x.st} TOTAL</span></div>`).join('')}</div></section><section class="panel"><div class="panel-pad"><h3 class="panel-title">Tips · MB + SM = 100</h3><p class="panel-caption">MOVEMENT / STABILITY</p></div><div class="table-list">${TIPS.map(x=>`<div class="table-row"><span class="rank-number">${x.id}</span><div><b>MB ${x.mb}</b><small>Stability ${x.sm}</small></div><span class="table-score">${x.mb+x.sm} TOTAL</span></div>`).join('')}</div></section><section class="panel panel-pad"><div class="eyebrow">BUILD THE COMBINATION</div><h3 class="panel-title" style="margin:9px 0">7,680 possible builds.</h3><p class="page-subtitle">Build variety comes from component combinations and player decisions. No inventory rarity and no stat boosts.</p><br><button class="primary-button" data-view="workshop">OPEN WORKSHOP ↗</button></section></div><div class="section-heading"><div><h2>Saved builds</h2><p>Stored locally in this browser</p></div><button class="text-link" data-view="workshop">CREATE BUILD ↗</button></div>${app.savedBuilds.length?`<div class="collection-grid">${app.savedBuilds.map((b,i)=>`<article class="collection-card"><i class="core-swatch" style="--swatch:${b.color};background:${b.color}"></i><b>${esc(b.name)}</b><small>${b.core} / ${b.blade} / ${b.disc} / ${b.tip}</small><div style="display:flex;gap:7px;margin-top:12px"><button class="text-link" data-use-build="${i}">USE</button><button class="text-link" data-delete-build="${i}">REMOVE</button></div></article>`).join('')}</div>`:`<div class="empty-state"><b>No saved builds yet.</b>Save a workshop build to keep it in your garage.</div>`}`}
function saveBuild(){const build=currentBuild();const prior=app.savedBuilds.findIndex(x=>x.name===build.name);const record={...build};if(prior>=0)app.savedBuilds[prior]=record;else app.savedBuilds.unshift(record);app.savedBuilds=app.savedBuilds.slice(0,30);save();showToast(`${build.name} saved to your garage.`);render()}
function loadBuild(index){const build=app.savedBuilds[index];if(!build)return;app.parts={core:build.core,blade:build.blade,disc:build.disc,tip:build.tip};app.buildName=build.name;save();go('workshop');showToast(`${build.name} loaded.`)}
function deleteBuild(index){app.savedBuilds.splice(index,1);save();render();showToast('Saved build removed.')}

