function deleteBuild(index){app.savedBuilds.splice(index,1);save();render();showToast('Saved build removed.')}

function arenaView(){if(!app.battle)return arenaLobby();return battleView()}
function arenaLobby(){return `<div class="eyebrow">COMPETE / LOCAL VERSUS</div><h1 class="page-title">Enter the arena.</h1><p class="page-subtitle">Two bladers. One device. Commit your move in private, then pass the controls. Both actions reveal only after the second player commits.</p><div class="hero-grid" style="margin-top:24px"><section class="panel panel-pad"><div class="eyebrow">YOUR ACTIVE BUILD</div><div class="build-showcase" style="padding:16px 0"><div class="build-visual">${artMarkup()}</div><div class="build-copy"><div class="build-name-row"><h3>${esc(currentBuild().name)}</h3><span class="type-tag">${currentBuild().classification.toUpperCase()}</span></div><div class="component-line">${componentLine(currentBuild())}</div><div class="stat-list">${statsMarkup(currentBuild().stats)}</div></div></div><button class="text-link" data-view="workshop">EDIT BUILD ↗</button></section><section class="panel match-card"><span class="eyebrow">LOCAL PASS-AND-PLAY</span><h3>Ready to launch?</h3><p>This prototype runs entirely in your browser. Player 1 launches first, then passes the device. Both actions are hidden until commitment.</p><div class="match-meta"><span>PLAYERS <b>2</b></span><span>TURN TIMER <b>NONE</b></span></div><button class="primary-button" data-start>LAUNCH MATCH ↗</button><p style="margin-top:14px;font-size:9px">Online matchmaking, accounts, and server play are not part of this local prototype.</p></section></div><div class="section-heading"><div><h2>Battle rules</h2><p>Five actions · three arena finish types</p></div></div><div class="collection-grid">${[['ATTACK','Strike to damage stability and pressure position.'],['DEFENSE','Mitigate hits; repeated guarding costs energy.'],['DODGE','Evade an attack, with diminishing returns.'],['CHARGE','Recover energy and build momentum.'],['SPECIAL','Spend 20 energy for a heavier impact.']].map(([a,b])=>`<div class="collection-card"><b>${a}</b><small>${b}</small></div>`).join('')}</div>`}
function startBattle(){app.battle=createBattle(currentBuild(),opponentBuild(),(Date.now()^Math.floor(Math.random()*0xffffffff))>>>0);app.phase='p1';app.p1Action=null;app.p2Action=null;app.view='arena';render();window.scrollTo(0,0)}
function passDevice(){app.phase='p2';render()}
function chooseAction(action){if(!ACTIONS.includes(action)||app.battle?.over)return;if(app.phase==='p1'){app.p1Action=action;app.phase='pass2';render();return}if(app.phase==='p2'){app.p2Action=action;resolveTurn(app.battle,app.p1Action,app.p2Action);app.phase='resolved';if(app.battle.over)recordResult();render()}}
function nextBattleTurn(){if(app.battle?.over){app.battle=null;app.phase='idle';render();return}app.phase='p1';app.p1Action=null;app.p2Action=null;render()}
function recordResult(){const battle=app.battle;if(!battle||battle._recorded)return;battle._recorded=true;const winner=battle.winner===-1?'draw':battle.winner===0?'you':'opponent';app.history.push({winner,reason:battle.reason,turns:battle.turn-1,build:battle.fighters[0].build.name,opponent:battle.fighters[1].build.name,date:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'})});app.history=app.history.slice(-100);save()}
function actionDescription(action){return ({attack:'Land a strike. Costs 5 energy.',defend:'Reduce incoming impact. Guarding fatigues.',dodge:'Evade a hit. Repeated dodges fade.',charge:'Recover energy and gain momentum.',special:'Heavy attack. Costs 20 energy.'})[action]}
function healthBar(fighter,key,enemy=false){const value=Math.round(fighter[key]);return `<div class="resource-block ${enemy?'enemy-resource':''}"><div class="resource-label"><span>${key==='energy'?'ENERGY':'STABILITY'}</span><b>${value}%</b></div><div class="resource-track"><div class="resource-fill ${key==='stability'?'stability':''}" style="width:${value}%"></div></div></div>`}
function arenaSVG(){return `<svg viewBox="0 0 220 140" aria-label="Arena ring"><defs><radialGradient id="ringFill"><stop offset="0" stop-color="#1a343f"/><stop offset=".72" stop-color="#111d26"/><stop offset="1" stop-color="#0c1219"/></radialGradient><linearGradient id="ringEdge"><stop stop-color="#43b8ca"/><stop offset=".5" stop-color="#d4edf0"/><stop offset="1" stop-color="#b87e5d"/></linearGradient></defs><ellipse cx="110" cy="78" rx="99" ry="46" fill="url(#ringFill)" stroke="#29414c" stroke-width="6"/><ellipse cx="110" cy="72" rx="94" ry="41" fill="none" stroke="url(#ringEdge)" stroke-width="2"/><ellipse cx="110" cy="72" rx="60" ry="26" fill="none" stroke="#447481" stroke-width="1" stroke-dasharray="3 4"/><ellipse cx="110" cy="72" rx="29" ry="12" fill="none" stroke="#45636c" stroke-width="1"/><path d="M13 78 19 96 48 109 110 124 172 109 201 96 207 78" fill="none" stroke="#29343e" stroke-width="4"/><path d="M18 72 110 72 202 72M110 33v79" stroke="#ffffff10" stroke-width="1" stroke-dasharray="2 5"/><circle cx="68" cy="63" r="3" fill="#6fe4ee"/><circle cx="151" cy="79" r="3" fill="#ff9b67"/></svg>`}
function fightCard(fighter,index){const enemy=index===1;return `<div class="fighter-card"><div class="fighter-top"><div><b>${esc(enemy?fighter.build.name:app.profile)}</b><small>${esc(fighter.build.name)} · ${fighter.build.classification.toUpperCase()}</small></div><span class="fighter-side-label ${enemy?'enemy':''}">${enemy?'PLAYER 2':'PLAYER 1'}</span></div><div class="fighter-art ${enemy?'enemy-art':''}">${artMarkup()}</div>${healthBar(fighter,'energy',enemy)}${healthBar(fighter,'stability',enemy)}</div>`}
function battleLogMarkup(){return `<div class="battle-log" aria-live="polite">${app.battle.log.slice().reverse().map(line=>`<div class="log-line ${line.kind}"><time>${line.turn?`T${line.turn}`:'SYS'}</time><span>${esc(line.text)}</span></div>`).join('')}</div>`}
function actionPicker(){const player=app.phase==='p2'?'PLAYER 2':'PLAYER 1';const fighter=app.battle.fighters[app.phase==='p2'?1:0];return `<section class="panel action-panel"><div class="action-header"><h3>${player} — Commit your move</h3><span>YOUR ACTION STAYS HIDDEN</span></div><div class="action-grid">${ACTIONS.map(action=>`<button class="action-button ${action==='special'?'special':''}" data-action="${action}" ${action==='special'&&(fighter.energy<20||fighter.specialCooldown>0)?'disabled':''}><b><span class="action-symbol">${({attack:'↗',defend:'⬡',dodge:'⌁',charge:'ϟ',special:'✦'})[action]}</span>${ACTION_LABELS[action]}</b><small>${actionDescription(action)}</small></button>`).join('')}</div><div class="commit-status">${app.phase==='p2'?'Choose Player 2 action. Player 1’s choice remains concealed.':'Choose an action, then pass the device. Your choice stays concealed.'}</div></section>`}
function privacyOverlay(){return `<div class="privacy-screen"><div><div class="privacy-mark">◈</div><div class="eyebrow">PRIVATE ACTION COMMITTED</div><h3>Pass the device.</h3><p>Player 1’s choice is locked away.<br>Hand the device to Player 2 before continuing.</p><button class="primary-button" data-privacy>PLAYER 2 READY ↗</button></div></div>`}
function revealMarkup(){return `<section class="panel action-panel"><div class="action-header"><h3>Turn ${app.battle.turn-1} — Actions revealed</h3><span>SIMULTANEOUS RESOLUTION</span></div><div class="action-reveal"><div>PLAYER 1<b>${ACTION_LABELS[app.p1Action]}</b></div><span class="reveal-vs">VS</span><div>PLAYER 2<b>${ACTION_LABELS[app.p2Action]}</b></div></div><div class="commit-status">${app.battle.log.at(-1)?.text||'Turn resolved.'}</div><button class="primary-button" style="width:100%;margin-top:10px" data-continue>${app.battle.over?'VIEW MATCH RESULT':'NEXT TURN ↗'}</button></section>`}
function resultMarkup(){const state=app.battle,draw=state.winner===-1,won=state.winner===0;return `<section class="panel battle-end"><div class="eyebrow">MATCH COMPLETE · ${state.reason.toUpperCase()}</div><h2>${draw?'DRAW':won?'VICTORY':'DEFEAT'}</h2><p>${draw?'Both Beyblades went down together.':won?`${esc(state.fighters[1].build.name)} is out of the arena.`:`${esc(state.fighters[0].build.name)} has been defeated.`} · ${state.turn-1} turns played.</p><div class="match-meta" style="justify-content:center"><span>BURSTS <b>${state.totals.bursts}</b></span><span>RING-OUTS <b>${state.totals.ringOuts}</b></span><span>SPIN FINISHES <b>${state.totals.spinFinishes}</b></span></div><div class="hero-cta"><button class="primary-button" data-rematch>REMATCH ↗</button><button class="secondary-button" data-results-home>COMMAND DECK</button></div></section>`}
function battleView(){const state=app.battle,f=state.fighters;let body='';if(state.over)body=resultMarkup();else if(app.phase==='resolved')body=revealMarkup();else body=actionPicker();return `<div class="battle-toolbar"><div><div class="eyebrow">LOCAL VERSUS / MATCH ${String(state.seed%9999).padStart(4,'0')}</div><h1 class="page-title">The arena.</h1></div><span class="battle-mode">PASS-AND-PLAY · PRIVATE ACTIONS</span></div><section class="arena-board"><div class="fighters ${app.phase==='resolved'?'is-battling':''}">${fightCard(f[0],0)}<div class="arena-center">${arenaSVG()}<div class="turn-indicator">${state.over?'MATCH COMPLETE':`ROUND ${String(state.turn).padStart(2,'0')} · SIMULTANEOUS TURN`}</div></div>${fightCard(f[1],1)}</div><div class="battle-hud"><span>ARENA STABILITY <b>${Math.max(0,100-state.turn*2)}%</b></span><span class="round-counter">TURN ${state.turn} / 30</span><span>INITIATIVE <b>${f[0].initiative?'PLAYER 1':'PLAYER 2'}</b></span></div></section>${battleLogMarkup()}${body}${app.phase==='pass2'?privacyOverlay():''}`}
function rankingsView(){return `<div class="eyebrow">ARENA NETWORK / OPEN CIRCUIT</div><h1 class="page-title">Rankings.</h1><p class="page-subtitle">The competitive ladder is designed for online play and is not active in this local prototype. No placeholder rankings or fabricated player records.</p><div class="empty-state" style="margin-top:25px"><b>Rankings are not connected.</b>Online accounts and server-authoritative match results are future milestones.<br><br><span class="panel-caption">LOCAL PROTOTYPE · NO NETWORK SERVICE</span></div><div class="section-heading"><div><h2>Competition principles</h2><p>What the leaderboard will measure</p></div></div><div class="collection-grid">${[['NO PROGRESSION','Player levels never improve combat stats.'],['OPEN COMPONENTS','Every blader gets access to the full component set.'],['SERVER VERIFIED','Ranked results require authoritative online match resolution.'],['SIM EVIDENCE','Balance claims require automated simulation data.']].map(([a,b])=>`<div class="collection-card"><b>${a}</b><small>${b}</small></div>`).join('')}</div>`}
function historyView(){return `<div class="eyebrow">YOUR GARAGE / MATCH RECORD</div><h1 class="page-title">Battle history.</h1><p class="page-subtitle">Results from matches played on this browser. Records are stored locally and can be cleared with browser storage.</p><div class="section-heading"><div><h2>${app.history.length} recorded match${app.history.length===1?'':'es'}</h2><p>Local-versus results only</p></div></div>${app.history.length?`<section class="panel match-history-list">${app.history.slice().reverse().map(historyRow).join('')}</section>`:`<div class="empty-state"><b>No matches on record.</b>Your first result appears here after completing a battle.<br><br><button class="primary-button" data-start>START A MATCH ↗</button></div>`}`}

