23: function homeView(){const build=currentBuild(),last=app.history.slice(-3).reverse();return `<div class="eyebrow">SEASON 01 / OPEN CIRCUIT</div><h1 class="page-title">Your command deck.</h1><p class="page-subtitle">Every part is a decision. Tune your build, read the arena, and take the ring.</p>
