36: function workshopView(){const build=currentBuild(),list=componentSets[app.tab];return `<div class="eyebrow">YOUR GARAGE / LIVE BUILD CALCULATOR</div><h1 class="page-title">The workshop.</h1><p class="page-subtitle">Four parts, one identity. See every stat shift as you tune your Beyblade. Cores are cosmetic; blades, discs, and tips carry explicit trade-offs.</p><div class="workshop-layout"><section class="panel builder-panel"><div class="panel-caption">01 / SELECT COMPONENTS</div><div class="component-tabs">${[['core','CORE'],['blade','BLADE'],['disc','DISC'],['tip','TIP']].map(([key,label])=>`<button class="component-tab ${app.tab===key?'selected':''}" data-tab="${key}"><strong>${label}</strong>${key==='core'?'COSMETIC':'8 OPTIONS'}</button>`).join('')}</div><div class="selection-heading"><b>${componentTitle(app.tab)}</b><span>${list.length} AVAILABLE</span></div><div class="option-grid">${list.map(item=>componentOption(app.tab,item)).join('')}</div><div class="builder-actions"><button class="secondary-button" data-new-build>RESET BUILD</button><button class="primary-button" data-save-build>SAVE TO GARAGE</button></div><p class="saved-build">Build choices save automatically on this device. No account or network required.</p></section>
