38: function collectionView(){return `<div class="eyebrow">YOUR GARAGE / COMPONENT INDEX</div><h1 class="page-title">The collection.</h1><p class="page-subtitle">Every part is available from the start. Performance components remain trade-offs, never rarity tiers.</p><div class="section-heading"><div><h2>15 cosmetic cores</h2><p>Color only · no combat advantage</p></div><span class="panel-caption">${collectionSummary()[0]}</span></div><div class="collection-grid">${CORES.map(core=>`<article class="collection-card"><i class="core-swatch" style="--swatch:${core.color};background:${core.color}"></i><b>${esc(core.name)}</b><small>${core.id} · COSMETIC CORE</small></article>`).join('')}</div><div class="section-heading"><div><h2>Performance components</h2><p>24 options · explicit paired-stat conservation</p></div></div><div class="two-col"><section class="panel"><div class="panel-pad"><h3 class="panel-title">Blades · AP + LI = 80</h3><p class="panel-caption">ATTACK POTENTIAL / IMPACT LOAD</p></div><div class="table-list">${BLADES.map(x=>`<div class="table-row"><span class="rank-number">${x.id}</span><div><b>AP ${x.ap}</b><small>Impact load ${x.li}</small></div><span class="table-score">${x.ap+x.li} TOTAL</span></div>`).join('')}</div></section><section class="panel"><div class="panel-pad"><h3 class="panel-title">Discs · MS + ST = 100</h3><p class="panel-caption">MOBILITY / STAMINA</p></div><div class="table-list">${DISCS.map(x=>`<div class="table-row"><span class="rank-number">${x.id}</span><div><b>MS ${x.ms}</b><small>Stamina ${x.st}</small></div><span class="table-score">${x.ms+x.st} TOTAL</span></div>`).join('')}</div></section><section class="panel"><div class="panel-pad"><h3 class="panel-title">Tips · MB + SM = 100</h3><p class="panel-caption">MOVEMENT / STABILITY</p></div><div class="table-list">${TIPS.map(x=>`<div class="table-row"><span class="rank-number">${x.id}</span><div><b>MB ${x.mb}</b><small>Stability ${x.sm}</small></div><span class="table-score">${x.mb+x.sm} ... (line truncated to 2000 chars)
39: function saveBuild(){const build=currentBuild();const prior=app.savedBuilds.findIndex(x=>x.name===build.name);const record={...build};if(prior>=0)app.savedBuilds[prior]=record;else app.savedBuilds.unshift(record);app.savedBuilds=app.savedBuilds.slice(0,30);save();showToast(`${build.name} saved to your garage.`);render()}
