12:   .map(([ms,st],i)=>({id:`D${String(i+1).padStart(2,'0')}`,ms,st}));
13: export const TIPS = [[50,50],[70,30],[85,15],[30,70],[15,85],[60,40],[40,60],[75,25]]
14:   .map(([mb,sm],i)=>({id:`T${String(i+1).padStart(2,'0')}`,mb,sm}));
