21: export function makeBuild({core='C01',blade='B01',disc='D01',tip='T01',name='Aetherion'}) {
22:   const c=CORES.find(x=>x.id===core)||CORES[0], b=BLADES.find(x=>x.id===blade)||BLADES[0], d=DISCS.find(x=>x.id===disc)||DISCS[0], t=TIPS.find(x=>x.id===tip)||TIPS[0];
23:   // Component conservation is preserved: each choice trades one paired stat for another.
24:   const stats={
25:     attack:round(clamp(50+(b.ap-40)*.62+(t.mb-50)*.18,20,80)),
26:     defense:round(clamp(50+(b.li-40)*.34+(d.st-50)*.34+(t.sm-50)*.22,20,80)),
27:     mobility:round(clamp(50+(t.mb-50)*.47+(d.ms-50)*.16+(b.ap-40)*.12,20,80)),
28:     stamina:round(clamp(50+(d.st-50)*.43+(t.sm-50)*.33+(b.li-40)*.14,20,80)),
29:     balance:round(clamp(50+(b.li-40)*.18+(d.ms-50)*.25+(t.sm-50)*.26,20,80))
30:   };
31:   const top=Math.max(stats.attack,stats.defense,stats.mobility,stats.stamina);
32:   const sorted=Object.entries(stats).filter(([k])=>k!=='balance').sort((a,b)=>b[1]-a[1]);
33:   const classification=top<55?'Balanced':sorted[0][0][0].toUpperCase()+sorted[0][0].slice(1);
34:   return {core:c.id,coreName:c.name,color:c.color,blade:b.id,disc:d.id,tip:t.id,name,stats,classification};
35: }
