37: export function createBattle(buildA, buildB, seed=0x5eed) {
38:   return {
39:     turn:1, seed:seed>>>0, over:false, winner:null, reason:null,
40:     fighters:[buildA,buildB].map((build,i)=>({build,energy:100,stability:100,position:30,momentum:0,defenseFatigue:0,dodgeDecay:0,initiative:i===0?1:0,adaptation:null,specialCooldown:0,bursts:0})),
41:     log:[{turn:0,text:'LAUNCH! Both bladers enter the arena.',kind:'system'}],
42:     totals:{bursts:0,ringOuts:0,spinFinishes:0}
43:   };
44: }
45: function rand(state) { state.seed=(Math.imul(state.seed,1664525)+1013904223)>>>0; return state.seed/4294967296; }
46: function adapt(fighter, action) { return fighter.adaptation===action ? 0 : fighter.adaptation ? 0.06 : 0; }
47: function finish(state, winner, reason) {
48:   state.over=true; state.winner=winner; state.reason=reason;
49:   if(reason==='Burst') state.totals.bursts++;
50:   if(reason==='Ring-Out') state.totals.ringOuts++;
51:   if(reason==='Spin Finish') state.totals.spinFinishes++;
52: }
