54: export function resolveTurn(state, actionA, actionB) {
55:   if(state.over) throw new Error('Match is already complete.');
56:   if(!ACTIONS.includes(actionA)||!ACTIONS.includes(actionB)) throw new Error('Choose a valid combat action.');
57:   const actions=[actionA,actionB], f=state.fighters, events=[];
58:   const initiative=f[0].build.stats.mobility+f[0].momentum >= f[1].build.stats.mobility+f[1].momentum ? 0:1;
59:   f.forEach((x,i)=>{ x.initiative=i===initiative?1:0; x.defenseFatigue=Math.max(0,x.defenseFatigue-.06); x.dodgeDecay=Math.max(0,x.dodgeDecay-.09); x.specialCooldown=Math.max(0,x.specialCooldown-1); });
60: 
61:   // Setup phase. Charge restores energy; defensive stances reduce damage but fatigue accumulates.
62:   for(let i=0;i<2;i++){
63:     const x=f[i], action=actions[i];
64:     if(action==='charge') { const gain=clamp(11+x.build.stats.stamina*.10-x.energy*.025,5,16); x.energy=clamp(x.energy+gain,0,100); x.momentum=clamp(x.momentum+.10,0,.7); events.push(`${x.build.name} charges +${Math.round(gain)} energy.`); }
65:     if(action==='defend') { x.defenseFatigue=clamp(x.defenseFatigue+.10,0,.5); x.position=Math.max(0,x.position-5); }
66:   }
67:   // Collisions are resolved simultaneously; stochastic collision checks have explicit bounds.
68:   const hits=[false,false], impacts=[0,0];
69:   for(let i=0;i<2;i++){
70:     const j=1-i, x=f[i], target=f[j], action=actions[i], targetAction=actions[j];
71:     if(!['attack','special'].includes(action)) continue;
72:     if(action==='special' && (x.energy<20||x.specialCooldown>0)) { events.push(`${x.build.name}'s Special is unavailable — energy preserved.`); continue; }
73:     const special=action==='special';
74:     if(special){ x.energy=clamp(x.energy-20,0,100); x.specialCooldown=2; }
75:     const base=action==='attack'?.57:.68;
76:     const collision=clamp(base+(x.build.stats.mobility-50)*.003+(x.momentum*.12)+(x.position-target.position)*.0015-(targetAction==='dodge'?.30:0)-target.dodgeDecay, .08,.94);
77:     if(rand(state)>=collision){ events.push(`${x.build.name} misses (${Math.round(collision*100)}% collision chance).`); continue; }
78:     hits[i]=true;
79:     const actionScale=special?1.55:1;
80:     const attack=(x.build.stats.attack*.42+25+x.momentum*14)*actionScale*(1+adapt(x,action));
81:     const guard=targetAction==='defend'?target.build.stats.defense*.42+18+target.defenseFatigue*22:target.build.stats.defense*.12+7;
82:     const evade=targetAction==='dodge'?target.build.stats.mobility*.19+target.dodgeDecay*18:0;
83:     const impact=clamp((attack-guard-evade)*(.70+rand(state)*.38),2,64);
84:     impacts[i]=impact;
85:     const stabilityDamage=clamp(impact*(.74+(100-target.stability)*.004),1,55);
86:     target.stability=clamp(target.stability-stabilityDamage,0,100);
87:     target.energy=clamp(target.energy-impact*(special?.34:.20),0,100);
88:     const pressure=clamp((x.build.stats.attack-target.build.stats.defense)*.0018+impact*.009+(special?.08:0),.02,.52);
89:     target.position=clamp(target.position+pressure*20+(rand(state)-.5)*2,0,105);
90:     x.momentum=clamp(x.momentum+.17+(special?.1:0),0,.7);
91:     x.position=clamp(x.position-3,0,105);
92:     events.push(`${x.build.name} ${special?'unleashes SPECIAL':'strikes'} for ${Math.round(impact)} impact.`);
93:     const burstChance=clamp(.015+(100-target.stability)*.0014+Math.max(0,impact-32)*.002,0,.22);
94:     if(target.stability<=0 || rand(state)<burstChance){ target.bursts++; finish(state,i,'Burst'); events.push(`${target.build.name} BURST!`); break; }
95:   }
96:   // Defensive resource decay is paid even on a missed collision, preventing infinite stall loops.
97:   for(let i=0;i<2&&!state.over;i++){
98:     const x=f[i], action=actions[i];
99:     if(action==='defend') x.energy=clamp(x.energy-3.5-x.defenseFatigue*4,0,100);
100:     else if(action==='dodge'){ x.dodgeDecay=clamp(x.dodgeDecay+.12,0,.5); x.energy=clamp(x.energy-5,0,100); x.position=Math.max(0,x.position-2); }
101:     else if(action==='attack') x.energy=clamp(x.energy-5,0,100);
102:     x.momentum=clamp(x.momentum*.76,0,.7);
103:     x.adaptation=action;
104:   }
105:   if(!state.over){
