107:     if(out[0]||out[1]){ const winner=out[0]&&out[1]?(f[0].energy>=f[1].energy?0:1):out[0]?1:0; finish(state,winner,'Ring-Out'); events.push(`${f[1-winner].build.name} is knocked out of the ring!`); }
108:     else if(f.some(x=>x.energy<=0)){ const winner=f[0].energy===f[1].energy?-1:f[0].energy>f[1].energy?0:1; finish(state,winner,'Spin Finish'); events.push(winner<0?'Both Beys lose spin!':'Spin Finish!'); }
